14: // CanonicalURL normalizes a Git remote URL into a canonical form:
15: // - Strips trailing .git and trailing slashes
16: // - Converts SSH/scp-like syntax (git@host:owner/repo) to https://host/owner/repo
17: // - Normalizes schemes (ssh://, git://) to https://
18: // - Lowercases the host component
19: func CanonicalURL(raw string) string {
20: 	raw = strings.TrimSpace(raw)
21: 	if raw == "" {
22: 		return ""
23: 	}
24: 	raw = strings.TrimSuffix(raw, "/")
25: 	raw = strings.TrimSuffix(raw, ".git")
26: 
27: 	// Match scp style: [user@]host:path
28: 	if !strings.Contains(raw, "://") && strings.Contains(raw, ":") {
29: 		parts := strings.SplitN(raw, ":", 2)
30: 		hostPart := parts[0]
31: 		pathPart := parts[1]
32: 		if atIdx := strings.Index(hostPart, "@"); atIdx != -1 {
33: 			hostPart = hostPart[atIdx+1:]
34: 		}
35: 		hostPart = strings.ToLower(hostPart)
36: 		pathPart = strings.TrimPrefix(pathPart, "/")
37: 		pathPart = strings.TrimSuffix(pathPart, "/")
38: 		pathPart = strings.TrimSuffix(pathPart, ".git")
39: 		return "https://" + hostPart + "/" + pathPart
40: 	}
41: 
42: 	// Match URL scheme: scheme://[user@]host[:port]/path
43: 	if u, err := url.Parse(raw); err == nil && u.Host != "" {
44: 		host := strings.ToLower(u.Hostname())
45: 		path := strings.TrimPrefix(u.Path, "/")
46: 		path = strings.TrimSuffix(path, "/")
47: 		path = strings.TrimSuffix(path, ".git")
48: 		return "https://" + host + "/" + path
49: 	}
50: 
51: 	return raw
52: }
