189: // GenerateRepoID generates the canonical Repo ID for the repository:
190: // sha256(root commit + ":" + canonical origin URL), falling back to main worktree real path if no remote URL exists.
191: func GenerateRepoID(repoRoot string) (string, error) {
192: 	rootCommit, err := GetRootCommit(repoRoot)
193: 	if err != nil {
