191: 	if entry, ok := reg[cleanPath]; ok {
192: 		return &entry, true, nil
193: 	}
194: 
195: 	// 2. Symlink-evaluated match
196: 	evalPath, err := filepath.EvalSymlinks(cleanPath)
197: 	if err == nil && evalPath != cleanPath {
198: 		if entry, ok := reg[evalPath]; ok {
199: 			return &entry, true, nil
200: 		}
201: 	}
202: 
203: 	// 3. Subdirectory match (workspace is inside an enrolled repository root/worktree)
204: 	for regPath, entry := range reg {
205: 		if isSubdir(cleanPath, regPath) {
206: 			return &entry, true, nil
207: 		}
208: 		if evalPath != "" && isSubdir(evalPath, regPath) {
209: 			return &entry, true, nil
210: 		}
211: 	}
212: 
213: 	return nil, false, nil
214: }
