217: 	rel, err := filepath.Rel(parent, child)
218: 	if err != nil {
219: 		return false
220: 	}
221: 	return rel != "." && !strings.HasPrefix(rel, "..") && !strings.HasPrefix(rel, "/") && !strings.HasPrefix(rel, `\`)
